CREATE TYPE "BillingPeriod" AS ENUM ('MONTHLY','SIX_MONTH','YEARLY'); CREATE TYPE "BillingRole" AS ENUM ('MANAGER','SALES');
CREATE TYPE "PaidSubscriptionStatus" AS ENUM ('ACTIVE','EXPIRED','CANCELLED','SUSPENDED'); CREATE TYPE "BillingOrderStatus" AS ENUM ('PENDING','PAID','FAILED','CANCELLED','EXPIRED');
CREATE TYPE "PaymentStatus" AS ENUM ('CREATED','AUTHORIZED','CAPTURED','FAILED','REFUNDED');
CREATE TYPE "BillingAuditType" AS ENUM ('PRICING_CHANGED','ORDER_CREATED','PAYMENT_CAPTURED','PAYMENT_FAILED','SUBSCRIPTION_ACTIVATED','SUBSCRIPTION_RENEWED','SEATS_CHANGED','SUPER_ADMIN_OVERRIDE','SUBSCRIPTION_SUSPENDED');
CREATE TABLE "billing_prices" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"role" "BillingRole" NOT NULL,"period" "BillingPeriod" NOT NULL,"amount" NUMERIC(18,2) NOT NULL,"currency" CHAR(3) NOT NULL DEFAULT 'INR',"effectiveFrom" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"effectiveUntil" TIMESTAMP(3),"createdByUserId" UUID,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "prices_check" CHECK("amount">0 AND "currency"~'^[A-Z]{3}$' AND ("effectiveUntil" IS NULL OR "effectiveUntil">"effectiveFrom")),FOREIGN KEY("createdByUserId") REFERENCES "users"("id") ON DELETE RESTRICT);
CREATE UNIQUE INDEX "billing_prices_current_key" ON "billing_prices"("role","period","currency") WHERE "effectiveUntil" IS NULL; CREATE INDEX "billing_prices_history_idx" ON "billing_prices"("role","period","effectiveFrom");
INSERT INTO "billing_prices"("role","period","amount") VALUES ('MANAGER','MONTHLY',200),('MANAGER','SIX_MONTH',1200),('MANAGER','YEARLY',2400),('SALES','MONTHLY',150),('SALES','SIX_MONTH',900),('SALES','YEARLY',1800);
CREATE TABLE "billing_orders" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"companyId" UUID NOT NULL,"createdByUserId" UUID NOT NULL,"billingPeriod" "BillingPeriod" NOT NULL,"managerSeats" INT NOT NULL,"salesSeats" INT NOT NULL,"managerUnitPrice" NUMERIC(18,2) NOT NULL,"salesUnitPrice" NUMERIC(18,2) NOT NULL,"currency" CHAR(3) NOT NULL,"subtotal" NUMERIC(18,2) NOT NULL,"taxAmount" NUMERIC(18,2) NOT NULL DEFAULT 0,"totalAmount" NUMERIC(18,2) NOT NULL,"status" "BillingOrderStatus" NOT NULL DEFAULT 'PENDING',"provider" VARCHAR(40) NOT NULL DEFAULT 'UNCONFIGURED',"providerOrderId" VARCHAR(200) UNIQUE,"idempotencyKey" VARCHAR(100) NOT NULL UNIQUE,"paidAt" TIMESTAMP(3),"expiresAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "order_seats_check" CHECK("managerSeats" BETWEEN 0 AND 10000 AND "salesSeats" BETWEEN 0 AND 10000 AND "managerSeats"+"salesSeats">0),CONSTRAINT "order_money_check" CHECK("managerUnitPrice">0 AND "salesUnitPrice">0 AND "subtotal"="managerUnitPrice"*"managerSeats"+"salesUnitPrice"*"salesSeats" AND "taxAmount">=0 AND "totalAmount"="subtotal"+"taxAmount" AND "currency"~'^[A-Z]{3}$'),FOREIGN KEY("companyId") REFERENCES "companies"("id") ON DELETE RESTRICT,FOREIGN KEY("createdByUserId","companyId") REFERENCES "users"("id","companyId") ON DELETE RESTRICT);
CREATE UNIQUE INDEX "billing_orders_id_company_key" ON "billing_orders"("id","companyId"); CREATE INDEX "billing_orders_company_created_idx" ON "billing_orders"("companyId","createdAt");
CREATE TABLE "payment_transactions" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"companyId" UUID NOT NULL,"orderId" UUID NOT NULL,"provider" VARCHAR(40) NOT NULL,"providerPaymentId" VARCHAR(200) NOT NULL UNIQUE,"amount" NUMERIC(18,2) NOT NULL,"currency" CHAR(3) NOT NULL,"status" "PaymentStatus" NOT NULL,"capturedAt" TIMESTAMP(3),"failureCode" VARCHAR(100),"failureMessage" VARCHAR(500),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "payment_check" CHECK("amount">0 AND "currency"~'^[A-Z]{3}$'),FOREIGN KEY("orderId","companyId") REFERENCES "billing_orders"("id","companyId") ON DELETE RESTRICT,FOREIGN KEY("companyId") REFERENCES "companies"("id") ON DELETE RESTRICT); CREATE INDEX "payments_company_created_idx" ON "payment_transactions"("companyId","createdAt"); CREATE INDEX "payments_order_idx" ON "payment_transactions"("orderId");
CREATE TABLE "company_subscriptions" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"companyId" UUID NOT NULL,"status" "PaidSubscriptionStatus" NOT NULL,"billingPeriod" "BillingPeriod" NOT NULL,"managerSeats" INT NOT NULL,"salesSeats" INT NOT NULL,"startsAt" TIMESTAMP(3) NOT NULL,"endsAt" TIMESTAMP(3) NOT NULL,"sourceOrderId" UUID UNIQUE,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "subscription_check" CHECK("managerSeats" BETWEEN 0 AND 10000 AND "salesSeats" BETWEEN 0 AND 10000 AND "startsAt"<"endsAt"),FOREIGN KEY("companyId") REFERENCES "companies"("id") ON DELETE RESTRICT,FOREIGN KEY("sourceOrderId","companyId") REFERENCES "billing_orders"("id","companyId") ON DELETE RESTRICT); CREATE INDEX "subscriptions_company_status_ends_idx" ON "company_subscriptions"("companyId","status","endsAt");
CREATE TABLE "billing_audit_events" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"companyId" UUID,"actorUserId" UUID,"type" "BillingAuditType" NOT NULL,"entityId" UUID,"reason" VARCHAR(500),"metadata" JSONB,"occurredAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("companyId") REFERENCES "companies"("id") ON DELETE RESTRICT,FOREIGN KEY("actorUserId") REFERENCES "users"("id") ON DELETE RESTRICT); CREATE INDEX "billing_audit_company_idx" ON "billing_audit_events"("companyId","occurredAt"); CREATE INDEX "billing_audit_type_idx" ON "billing_audit_events"("type","occurredAt");
CREATE FUNCTION prevent_billing_audit_mutation() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'billing audit is append-only';END$$; CREATE TRIGGER "billing_audit_append_only" BEFORE UPDATE OR DELETE ON "billing_audit_events" FOR EACH ROW EXECUTE FUNCTION prevent_billing_audit_mutation();
CREATE FUNCTION prevent_paid_order_snapshot_mutation() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF OLD.status='PAID' AND (NEW."managerSeats",NEW."salesSeats",NEW."managerUnitPrice",NEW."salesUnitPrice",NEW.currency,NEW.subtotal,NEW."taxAmount",NEW."totalAmount") IS DISTINCT FROM (OLD."managerSeats",OLD."salesSeats",OLD."managerUnitPrice",OLD."salesUnitPrice",OLD.currency,OLD.subtotal,OLD."taxAmount",OLD."totalAmount") THEN RAISE EXCEPTION 'paid order snapshot is immutable'; END IF; RETURN NEW; END$$; CREATE TRIGGER "paid_order_snapshot_immutable" BEFORE UPDATE ON "billing_orders" FOR EACH ROW EXECUTE FUNCTION prevent_paid_order_snapshot_mutation();
